# (maple/gga_exc/gga_x_wpbeh.mpl, maple/scaling.mpl, maple/util.mpl;
# Copyright (C) 2017 M.A.L. Marques, MPL 2.0).  The file is a new
# multi-precision implementation written for testing; it contains no code
# generated by libxc.
"""
wpbeh_reference.py -- multi-precision reference ("oracle") for the short-range
omega-PBE exchange (wPBEh) of HSE06, milestone M1 of EXX_IMPLEMENTATION_GUIDE.md
(OpenMX 4.0 GPU).

What it evaluates
  The mathematical definition of the functional GGA_X_WPBEH of libxc 7.1.2, with
  50 significant digits (mpmath).  It does not call libxc.  When this file was
  written its numbers had not been compared with the output of libxc; that
  comparison is the first step of M1 (--compare-pyscf).

Definition (one spin channel with density rho_s and gradient grad rho_s)
  kF    = (6 pi^2 rho_s)^(1/3)                     w = omega / kF
  s_raw = |grad rho_s| / (2 (6 pi^2)^(1/3) rho_s^(4/3))
  s     = rescale(s_raw)        variant "libxc":  s_raw for s_raw < 1,
                                s_raw - log(1 + exp(s_raw - 8.572844)) up to 15, 8.572844 above
  e_s   = -(3/4) (6/pi)^(1/3) rho_s^(4/3) f(w, s)                 energy per volume
  e     = e_up + e_down
  f(w, s) is the enhancement factor of Heyd, Scuseria and Ernzerhof built on the
  exchange hole of Ernzerhof and Perdew.  libxc 7.1.2 computes three constants
  (E, Fc1, Fc2) from the other hole parameters instead of using the rounded
  published values; variant "libxc" does the same.
  Variant "hse-original" uses the published constants, the three-term polynomial
  for EG below s = 0.08 and the rescaling of Heyd (s > 8.3), as coded in
  Quantum ESPRESSO 7.6 (XClib/qe_funct_exch_gga.f90).  It exists for comparison.

Output conventions (those of openmx_xc_kernel_pbe in modules/xc)
  exc      e / (rho_up + rho_down)                 libxc: zk
  dexdd    d e / d rho_s                           libxc: vrho[s]
  dexdgd   d e / d (d_i rho_s)                     libxc: 2 vsigma[ss] d_i rho_s

Usage
  python3 wpbeh_reference.py                   # self-test
  python3 wpbeh_reference.py --report          # effect of the formula choices
  python3 wpbeh_reference.py --dump FILE       # fixture for the unit tests
  python3 wpbeh_reference.py --point RU RD GUX GUY GUZ GDX GDY GDZ   # one point, with intermediates
  python3 wpbeh_reference.py --double          # double-precision prototype against the fixture (NumPy, SciPy)
  python3 wpbeh_reference.py --compare-pyscf   # compare the fixture points with libxc through PySCF

How the closed form was checked
  The self-test integrates the model exchange hole numerically and compares the result with
  the closed form (T13).  The constants were read in two sources, libxc 7.1.2 and Quantum
  ESPRESSO 7.6.
"""
import argparse
import sys

from mpmath import mp, mpf, sqrt, pi, exp, erf, erfc, e1, log, cbrt, diff, nstr, quad, inf

mp.dps = 50
OMEGA_HSE06 = "0.11"

# ----------------------------------------------------------------------------
# constants
A = mpf("1.0161144")
B = mpf("-0.37170836")
C = mpf("-0.077215461")
D = mpf("0.57786348")
HA = [mpf(x) for x in ("0.00979681", "0.0410834", "0.187440", "0.00120824", "0.0347188")]
EA = [mpf(x) for x in ("-1.128223946706117", "1.452736265762971", "-1.243162299390327",
                       "0.971824836115601", "-0.568861079687373", "0.246880514820192",
                       "-0.065032363850763", "0.008401793031216")]
EB1 = mpf("1.455915450052607")
WCUT = 14                      # above: Gaussian approximation of the first term
SMAX = mpf("8.572844")
# published (rounded) values
E_PUBLISHED = mpf("-0.051955731")
FC_PUBLISHED = (mpf("6.4753871"), mpf("0.47965830"))
EGA_PUBLISHED = [mpf(x) for x in ("-0.02628417880", "-0.07117647788", "0.08534541323")]
EGSCUT = mpf("0.08")
HEYD_STRANS, HEYD_SCONST = mpf("8.3"), mpf("18.79622316")
# values that follow from A, B, C, D:  E from the regularity of EG at s = 0
E_EXACT = (12 * sqrt(pi) * (sqrt(A) - 1) * D ** (mpf(7) / 2)
           - (6 * C * D + 4 * B * D ** 2 + 8 * A * D ** 3)) / 15
FC_EXACT = (4 * A ** 2 / (9 * C) + (B - A * D) / C, -mpf(4) / (108 * C))
# PBE exchange, for the comparison with the omega = 0 limit
KAPPA = mpf("0.804")
MU = mpf("0.06672455060314922") * pi ** 2 / 3

VARIANTS = ("libxc", "hse-original")


def erfcx(u):
    return exp(u * u) * erfc(u)


def e1_scaled(x):
    return exp(x) * e1(x)


# ----------------------------------------------------------------------------
# enhancement factor
def hole_h(s):
    return (HA[0] * s ** 2 + HA[1] * s ** 4) / (1 + HA[2] * s ** 4 + HA[3] * s ** 5 + HA[4] * s ** 6)


def g_a(s, e_const, fc):
    a1 = D + s * s * hole_h(s)
    a2 = 9 * hole_h(s) * s * s / (4 * A)
    f_s = fc[0] * hole_h(s) + fc[1]
    return (sqrt(pi) * (15 * e_const + 6 * C * (1 + f_s * s * s) * a1 + 4 * B * a1 ** 2 + 8 * A * a1 ** 3)
            / (16 * a1 ** (mpf(7) / 2)) - (3 * pi / 4) * sqrt(A) * erfcx(sqrt(a2)))


def hole_eg(s, variant):
    """EG(s).  Evaluated from the exact expression (50 digits make the 0/0 at small s harmless)."""
    if variant == "hse-original":
        if s <= EGSCUT:
            return EGA_PUBLISHED[0] + EGA_PUBLISHED[1] * s ** 2 + EGA_PUBLISHED[2] * s ** 4
        e_const, fc = E_PUBLISHED, FC_PUBLISHED
    else:
        e_const, fc = E_EXACT, FC_EXACT
    a1 = D + s * s * hole_h(s)
    g_b = 15 * sqrt(pi) * s * s / (16 * a1 ** (mpf(7) / 2))
    return -(3 * pi / 4 + g_a(s, e_const, fc)) / g_b


def enhancement_terms(w, s, variant="libxc"):
    """Terms of f(w, s) = -(8/9) (term1 + term2 + term3 + term4 + term5); s is the rescaled gradient."""
    if variant not in VARIANTS:
        raise ValueError("unknown variant %r" % (variant,))
    w, s = mpf(w), mpf(s)
    e_const = E_EXACT if variant == "libxc" else E_PUBLISHED
    fc = FC_EXACT if variant == "libxc" else FC_PUBLISHED
    eb1 = EB1 if w < WCUT else mpf(2)
    h = hole_h(s)
    f_s = fc[0] * h + fc[1]
    eg = hole_eg(s, variant)
    s2 = s * s
    a1 = D + s2 * h
    a3 = a1 + w * w
    a4 = s2 * h + eb1 * w * w
    a5 = 9 * a4 / (4 * A)
    a6 = D + a4
    p52 = a3 ** (mpf(5) / 2)
    term2 = (a1 ** 2 * B + a1 * C + 2 * e_const + a1 * s2 * C * f_s + 2 * s2 * eg) / (2 * a1 ** 3)
    term3 = -w * (4 * a3 ** 2 * B + 6 * a3 * C + 15 * e_const + 6 * a3 * s2 * C * f_s + 15 * s2 * eg) / (8 * a1 * p52)
    term4 = -w ** 3 * (a3 * C + 5 * e_const + a3 * s2 * C * f_s + 5 * s2 * eg) / (2 * a1 ** 2 * p52)
    term5 = -w ** 5 * (e_const + s2 * eg) / (a1 ** 3 * p52)
    if w > WCUT:
        term1 = -A / 2 * (-e1_scaled(a5) + log(a6 / a4))
    else:
        np1 = (-mpf("1.5") * EA[0] * sqrt(A) * w + 27 * EA[2] * w ** 3 / (8 * sqrt(A))
               - 243 * EA[4] * w ** 5 / (32 * A ** (mpf(3) / 2)) + 2187 * EA[6] * w ** 7 / (128 * A ** (mpf(5) / 2)))
        np2 = (-A + 9 * EA[1] * w ** 2 / 4 - 81 * EA[3] * w ** 4 / (16 * A)
               + 729 * EA[5] * w ** 6 / (64 * A ** 2) - 6561 * EA[7] * w ** 8 / (256 * A ** 3))
        t1 = (np1 * pi * erfcx(sqrt(a5)) - np2 * e1_scaled(a5)) / 2
        t10 = A / 2 * log(a4 / a6)
        t2t9 = mpf(0)
        if w != 0:
            f2 = EA[0] * sqrt(pi) * A / sqrt(a6) / 2
            f3 = EA[1] * A / a6 / 2
            f4 = EA[2] * sqrt(pi) * (-mpf(9) / (8 * sqrt(a4)) + A / (4 * a6 ** (mpf(3) / 2)))
            f5 = (EA[3] / 128) * (-144 / a4 + 64 * A / a6 ** 2)
            f6 = EA[4] * (3 * sqrt(pi) * (3 * a6 ** (mpf(5) / 2) * (9 * a4 - 2 * A) + 4 * a4 ** (mpf(3) / 2) * A ** 2)) \
                / (32 * a6 ** (mpf(5) / 2) * a4 ** (mpf(3) / 2) * A)
            f7 = EA[5] * (32 * A / a6 ** 3 + (-36 + 81 * s2 * h / A) / a4 ** 2) / 32
            f8 = EA[6] * (-3 * sqrt(pi) * (-40 * a4 ** (mpf(5) / 2) * A ** 3
                                           + 9 * a6 ** (mpf(7) / 2) * (27 * a4 ** 2 - 6 * a4 * A + 4 * A ** 2))) \
                / (128 * a6 ** (mpf(7) / 2) * a4 ** (mpf(5) / 2) * A ** 2)
            f9 = (324 * EA[5] * eb1 * a6 ** 4 * a4 * A
                  + EA[7] * (384 * a4 ** 3 * A ** 3 + a6 ** 4 * (-729 * a4 ** 2 + 324 * a4 * A - 288 * A ** 2))) \
                / (128 * a6 ** 4 * a4 ** 3 * A ** 2)
            t2t9 = (f2 * w + f3 * w ** 2 + f4 * w ** 3 + f5 * w ** 4 + f6 * w ** 5 + f7 * w ** 6
                    + f8 * w ** 7 + f9 * w ** 8)
        term1 = t1 + t2t9 + t10
    return {"H": h, "F": f_s, "EG": eg, "term1": term1, "term2": term2, "term3": term3,
            "term4": term4, "term5": term5}


def enhancement(w, s, variant="libxc"):
    t = enhancement_terms(w, s, variant)
    return -mpf(8) / 9 * (t["term1"] + t["term2"] + t["term3"] + t["term4"] + t["term5"])


def rescale(s_raw, variant="libxc"):
    s_raw = mpf(s_raw)
    if variant == "hse-original":
        return s_raw if s_raw <= HEYD_STRANS else SMAX - HEYD_SCONST / s_raw ** 2
    if s_raw < 1:
        return max(s_raw, mpf("1e-15"))
    if s_raw > 15:
        return SMAX
    return s_raw - log(1 + exp(s_raw - SMAX))


def f_pbe(s):
    return 1 + KAPPA - KAPPA / (1 + MU * mpf(s) ** 2 / KAPPA)


def f_lda_sr(w):
    """Exact short-range attenuation of LDA exchange for erfc(omega r)/r, a = omega/(2 kF)."""
    a = mpf(w) / 2
    if a == 0:
        return mpf(1)
    b = exp(-1 / (4 * a * a)) - 1
    return 1 - mpf(8) / 3 * a * (sqrt(pi) * erf(1 / (2 * a)) + 2 * a * (b - (2 * a * a * b + mpf(1) / 2)))


# ----------------------------------------------------------------------------
# energy density and derivatives
def channel_variables(rho_s, gamma_s, omega):
    k_f = cbrt(6 * pi ** 2 * rho_s)
    s_raw = gamma_s / (2 * cbrt(6 * pi ** 2) * rho_s ** (mpf(4) / 3))
    return omega / k_f, s_raw


def channel_energy(rho_s, gamma_s, omega, variant="libxc"):
    """Short-range exchange energy per volume of one spin channel; gamma_s = |grad rho_s|."""
    w, s_raw = channel_variables(rho_s, gamma_s, omega)
    return -mpf(3) / 4 * cbrt(6 / pi) * rho_s ** (mpf(4) / 3) * enhancement(w, rescale(s_raw, variant), variant)


def tolerance(w):
    """Relative tolerance for a double-precision implementation: 100 times an upper envelope of the
    rounding error of the direct formula (largest between w = 4 and w = 14, where the terms cancel).
    Above w = 14 the value is accurate to about 1e-11, the gradient derivative to about 1e-9."""
    w = float(w)
    if w >= WCUT:
        return 1e-9
    if w <= 4.0:
        return max(1e-12, 1e-13 * 10.0 ** (1.5 * w))
    return 1e-7 * 10.0 ** (0.5 * (w - 4.0))


def rounding_error(w, s, variant="libxc"):
    """Relative error of a 16-digit evaluation of the direct formula."""
    ref = enhancement(w, s, variant)
    old = mp.dps
    mp.dps = 16
    try:
        val = +enhancement(w, s, variant)
    finally:
        mp.dps = old
    return abs(val - ref) / abs(ref)


def evaluate(rho, grad, omega=OMEGA_HSE06, variant="libxc"):
    """rho = (up, down); grad = ((x, y, z) of up, (x, y, z) of down).  Returns a dict of mpf values."""
    omega = mpf(omega)
    out = {"e_s": [], "dexdd": [], "dexdgd": [], "vsigma": [], "w": [], "s_raw": [], "s": [], "tol": []}
    for sp in range(2):
        r = mpf(rho[sp])
        g = [mpf(x) for x in grad[sp]]
        gamma = sqrt(g[0] ** 2 + g[1] ** 2 + g[2] ** 2)
        if gamma == 0:
            raise ValueError("zero gradient: the derivative with respect to the gradient is taken per direction")
        w, s_raw = channel_variables(r, gamma, omega)
        de_dgamma = diff(lambda x: channel_energy(r, x, omega, variant), gamma)
        out["e_s"].append(channel_energy(r, gamma, omega, variant))
        out["dexdd"].append(diff(lambda x: channel_energy(x, gamma, omega, variant), r))
        out["dexdgd"].append([de_dgamma * g[i] / gamma for i in range(3)])
        out["vsigma"].append(de_dgamma / (2 * gamma))
        out["w"].append(w)
        out["s_raw"].append(s_raw)
        out["s"].append(rescale(s_raw, variant))
        out["tol"].append(tolerance(w))
    out["e"] = out["e_s"][0] + out["e_s"][1]
    out["exc"] = out["e"] / (mpf(rho[0]) + mpf(rho[1]))
    return out


# ----------------------------------------------------------------------------
# fixture
SPIN_DENSITIES = ("5", "0.5", "0.05", "5e-3", "5e-4", "5e-5", "5e-6", "5e-7", "4.4e-8", "5e-9")
REDUCED_GRADIENTS = ("0.003", "0.05", "0.079", "0.081", "0.129", "0.131", "0.4", "0.9", "0.999", "1.001",
                     "1.7", "3", "6", "9", "14.9", "15.1")
DIRECTIONS = (("0.6", "-0.48", "0.64"), ("-0.28", "0.96", "0"))
COLUMNS = ("rho_up rho_dn gup_x gup_y gup_z gdn_x gdn_y gdn_z e_up e_dn exc dexdd_up dexdd_dn "
           "dexdgd_x_up dexdgd_y_up dexdgd_z_up dexdgd_x_dn dexdgd_y_dn dexdgd_z_dn vsigma_upup vsigma_dndn "
           "w_up s_up w_dn s_dn tol_up tol_dn").split()


def fixture_points():
    """Each (density, reduced gradient) pair appears once in the up and once in the down channel."""
    combos = [(mpf(r), mpf(s)) for r in SPIN_DENSITIES for s in REDUCED_GRADIENTS]
    n = len(combos)
    points = []
    for i in range(n):
        chans = (combos[i], combos[(7 * i + 3) % n])
        rho, grad = [], []
        for sp, (r, s_raw) in enumerate(chans):
            gamma = s_raw * 2 * cbrt(6 * pi ** 2) * r ** (mpf(4) / 3)
            sign = -1 if (i + sp) % 2 else 1
            # the reference values belong to the double-precision inputs that are written to the file
            rho.append(mpf(float(r)))
            grad.append([mpf(float(sign * gamma * mpf(c))) for c in DIRECTIONS[sp]])
        points.append((rho, grad))
    return points


def fixture_rows(omega=OMEGA_HSE06, variant="libxc"):
    rows = []
    for rho, grad in fixture_points():
        v = evaluate(rho, grad, omega, variant)
        rows.append([rho[0], rho[1]] + grad[0] + grad[1] + v["e_s"] + [v["exc"]] + v["dexdd"]
                    + v["dexdgd"][0] + v["dexdgd"][1] + v["vsigma"]
                    + [v["w"][0], v["s"][0], v["w"][1], v["s"][1], mpf(v["tol"][0]), mpf(v["tol"][1])])
    return rows


def write_fixture(path, omega=OMEGA_HSE06):
    rows = fixture_rows(omega)
    with open(path, "w") as fh:
        fh.write("wpbeh_fixture 1\n")
        fh.write("definition libxc-7.1.2 GGA_X_WPBEH (evaluated with %d digits, not an output of libxc)\n" % mp.dps)
        fh.write("omega %s\n" % omega)
        fh.write("npoints %d\n" % len(rows))
        fh.write("ncolumns %d\n" % len(COLUMNS))
        fh.write("# " + " ".join(COLUMNS) + "\n")
        fh.write("# e_up + e_dn is the energy per volume; s_up and s_dn are the rescaled reduced gradients;\n")
        fh.write("# tol_* is the relative tolerance of that channel: |d e| <= tol_up |e_up| + tol_dn |e_dn|,\n")
        fh.write("# |d dexdd_s| <= 10 tol_s |dexdd_s|, |d dexdgd_i_s| <= 10 tol_s max(|dexdgd_s|, 1e-6 |e_s| / |grad rho_s|)\n")
        for row in rows:
            fh.write(" ".join("%.17e" % float(x) for x in row) + "\n")
    if read_fixture(path) != [[float(x) for x in row] for row in rows]:
        raise RuntimeError("the fixture does not read back identically")
    return len(rows)


def read_fixture(path):
    rows = []
    with open(path) as fh:
        for line in fh:
            parts = line.split()
            if parts and parts[0][0] in "+-0123456789":
                rows.append([float(x) for x in parts])
    return rows


# ----------------------------------------------------------------------------
# the defining integral (independent of the closed form)
def hole_integrals(w, s):
    """f(w, s) = -(8/9) (I1 + I2) by numerical quadrature of the model exchange hole.

    I1 = int dy y [-A/(y^2 (1 + 4A y^2/9)) + A exp(-D y^2)/y^2] exp(-s^2 H y^2) erfc_fit(w y)
    I2 = int dy y [B + C (1 + s^2 F) y^2 + (E + s^2 EG) y^4] exp(-(D + s^2 H) y^2) erfc(w y)
    erfc_fit(x) = (1 + sum_k ea_k x^k) exp(-eb1 x^2) below w = 14 and exp(-2 x^2) above.
    Returns (I1, I2); the closed form has term1 = I1 and term2 + ... + term5 = I2.
    """
    w, s = mpf(w), mpf(s)
    h = hole_h(s)
    f_s = FC_EXACT[0] * h + FC_EXACT[1]
    q = E_EXACT + s * s * hole_eg(s, "libxc")

    def erfc_fit(x):
        if w > WCUT:
            return exp(-2 * x * x)
        return (1 + sum(EA[k] * x ** (k + 1) for k in range(8))) * exp(-EB1 * x * x)

    def i1(y):
        if y == 0:
            return mpf(0)
        return (y * (-A / (y * y * (1 + 4 * A * y * y / 9)) + A * exp(-D * y * y) / (y * y))
                * exp(-s * s * h * y * y) * erfc_fit(w * y))

    def i2(y):
        return y * (B + C * (1 + s * s * f_s) * y * y + q * y ** 4) * exp(-(D + s * s * h) * y * y) * erfc(w * y)

    pts = [0, mpf("0.05"), mpf("0.3"), 1, 3, 10, 40, 200, inf]
    return quad(i1, pts), quad(i2, pts)


def hole_integral_deviation(points):
    """Largest |closed form - quadrature| / |f| over the given (w, s) pairs, at 30 digits."""
    old = mp.dps
    mp.dps = 30
    try:
        worst = mpf(0)
        for w, s in points:
            a, b = hole_integrals(w, s)
            t = enhancement_terms(w, s)
            f = enhancement(w, s)
            worst = max(worst, abs(a - t["term1"]) / abs(f),
                        abs(b - (t["term2"] + t["term3"] + t["term4"] + t["term5"])) / abs(f))
        return worst
    finally:
        mp.dps = old


# ----------------------------------------------------------------------------
# double-precision prototype
def double_channel_energy(rho, gamma, omega):
    """Double precision (complex arguments allowed, for complex-step derivatives).

    The hole function EG enters only as Q = E + s^2 EG.  Q is evaluated as
    E - (3 pi/4 + Ga(s)) 16 a1^(7/2) / (15 sqrt(pi)), without a division by s^2, and
    log(a4/a6) as -log1p(D/a4).  With this form no series in s is needed for the value
    and the first derivatives.
    """
    import numpy as np
    from scipy.special import erfcx as np_erfcx, exp1

    a_, b_, c_, d_ = float(A), float(B), float(C), float(D)
    ha = [float(x) for x in HA]
    ea = [float(x) for x in EA]
    e_const, fc1, fc2 = float(E_EXACT), float(FC_EXACT[0]), float(FC_EXACT[1])
    sqpi = np.sqrt(np.pi)

    def e1s(x):
        if abs(x) < 30.0:
            return np.exp(x) * exp1(x)
        val = 0.0
        for k in range(60, 0, -1):      # continued fraction 1/(x + 1 - 1/(x + 3 - 4/(x + 5 - ...)))
            val = k * k / (x + 2 * k + 1 - val)
        return 1.0 / (x + 1 - val)

    kf = (6 * np.pi ** 2 * rho) ** (1.0 / 3.0)
    s = gamma / (2 * (6 * np.pi ** 2) ** (1.0 / 3.0) * rho ** (4.0 / 3.0))
    w = omega / kf
    if s.real >= 1:
        s = float(SMAX) + 0 * s if s.real > 15 else s - np.log1p(np.exp(s - float(SMAX)))
    eb1 = float(EB1) if w.real < WCUT else 2.0
    h = (ha[0] * s ** 2 + ha[1] * s ** 4) / (1 + ha[2] * s ** 4 + ha[3] * s ** 5 + ha[4] * s ** 6)
    f_s = fc1 * h + fc2
    s2 = s * s
    a1 = d_ + s2 * h
    a2 = 9 * h * s2 / (4 * a_)
    a3 = a1 + w * w
    a4 = s2 * h + eb1 * w * w
    a5 = 9 * a4 / (4 * a_)
    a6 = d_ + a4
    a172 = a1 ** 3.5
    ga = sqpi * (15 * e_const + 6 * c_ * (1 + f_s * s2) * a1 + 4 * b_ * a1 ** 2 + 8 * a_ * a1 ** 3) / (16 * a172) \
        - 0.75 * np.pi * np.sqrt(a_) * np_erfcx(np.sqrt(a2))
    q = e_const - (0.75 * np.pi + ga) * 16 * a172 / (15 * sqpi)
    p52 = a3 ** 2.5
    term2 = (a1 ** 2 * b_ + a1 * c_ + a1 * s2 * c_ * f_s + 2 * q) / (2 * a1 ** 3)
    term3 = -w * (4 * a3 ** 2 * b_ + 6 * a3 * c_ + 6 * a3 * s2 * c_ * f_s + 15 * q) / (8 * a1 * p52)
    term4 = -w ** 3 * (a3 * c_ + a3 * s2 * c_ * f_s + 5 * q) / (2 * a1 ** 2 * p52)
    term5 = -w ** 5 * q / (a1 ** 3 * p52)
    if w.real > WCUT:
        term1 = -a_ / 2 * (-e1s(a5) + np.log1p(d_ / a4))
    else:
        sa = np.sqrt(a_)
        np1 = (-1.5 * ea[0] * sa * w + 27 * ea[2] * w ** 3 / (8 * sa) - 243 * ea[4] * w ** 5 / (32 * a_ ** 1.5)
               + 2187 * ea[6] * w ** 7 / (128 * a_ ** 2.5))
        np2 = (-a_ + 9 * ea[1] * w ** 2 / 4 - 81 * ea[3] * w ** 4 / (16 * a_) + 729 * ea[5] * w ** 6 / (64 * a_ ** 2)
               - 6561 * ea[7] * w ** 8 / (256 * a_ ** 3))
        t1 = 0.5 * (np1 * np.pi * np_erfcx(np.sqrt(a5)) - np2 * e1s(a5))
        t10 = -0.5 * a_ * np.log1p(d_ / a4)
        f2 = 0.5 * ea[0] * sqpi * a_ / np.sqrt(a6)
        f3 = 0.5 * ea[1] * a_ / a6
        f4 = ea[2] * sqpi * (-9 / (8 * np.sqrt(a4)) + 0.25 * a_ / a6 ** 1.5)
        f5 = (ea[3] / 128) * (-144 / a4 + 64 * a_ / a6 ** 2)
        f6 = ea[4] * (3 * sqpi * (3 * a6 ** 2.5 * (9 * a4 - 2 * a_) + 4 * a4 ** 1.5 * a_ ** 2)) \
            / (32 * a6 ** 2.5 * a4 ** 1.5 * a_)
        f7 = ea[5] * (32 * a_ / a6 ** 3 + (-36 + 81 * s2 * h / a_) / a4 ** 2) / 32
        f8 = ea[6] * (-3 * sqpi * (-40 * a4 ** 2.5 * a_ ** 3
                                   + 9 * a6 ** 3.5 * (27 * a4 ** 2 - 6 * a4 * a_ + 4 * a_ ** 2))) \
            / (128 * a6 ** 3.5 * a4 ** 2.5 * a_ ** 2)
        f9 = (324 * ea[5] * eb1 * a6 ** 4 * a4 * a_
              + ea[7] * (384 * a4 ** 3 * a_ ** 3 + a6 ** 4 * (-729 * a4 ** 2 + 324 * a4 * a_ - 288 * a_ ** 2))) \
            / (128 * a6 ** 4 * a4 ** 3 * a_ ** 2)
        term1 = t1 + t10 + (f2 * w + f3 * w ** 2 + f4 * w ** 3 + f5 * w ** 4 + f6 * w ** 5 + f7 * w ** 6
                            + f8 * w ** 7 + f9 * w ** 8)
    f = -8.0 / 9.0 * (term1 + term2 + term3 + term4 + term5)
    return -0.75 * (6 / np.pi) ** (1.0 / 3.0) * rho ** (4.0 / 3.0) * f


def double_check(omega=OMEGA_HSE06):
    """Double-precision prototype against the fixture values, with the tolerances of the fixture."""
    import numpy as np
    rows = [[float(x) for x in row] for row in fixture_rows(omega)]
    col = {name: i for i, name in enumerate(COLUMNS)}
    om = float(omega)
    classes = {}
    worst = 0.0
    for row in rows:
        for sp, name in enumerate(("up", "dn")):
            rho = row[sp]
            g = np.array(row[2 + 3 * sp:5 + 3 * sp])
            gamma = float(np.sqrt(np.sum(g * g)))
            tol = row[col["tol_" + name]]
            e = double_channel_energy(complex(rho), complex(gamma), om).real
            de_dr = double_channel_energy(complex(rho, rho * 1e-30), complex(gamma), om).imag / (rho * 1e-30)
            de_dg = double_channel_energy(complex(rho), complex(gamma, gamma * 1e-30), om).imag / (gamma * 1e-30)
            e_ref, d_ref = row[col["e_" + name]], row[col["dexdd_" + name]]
            g_ref = np.array([row[col["dexdgd_%s_%s" % (ax, name)]] for ax in "xyz"])
            scale = max(float(np.sqrt(np.sum(g_ref * g_ref))), 1e-6 * abs(e_ref) / gamma)
            dev = (abs(e - e_ref) / abs(e_ref), abs(de_dr - d_ref) / abs(d_ref),
                   float(np.max(np.abs(de_dg * g / gamma - g_ref))) / scale)
            c = classes.setdefault(tol, [0.0, 0.0, 0.0])
            for i in range(3):
                c[i] = max(c[i], dev[i])
            worst = max(worst, dev[0] / tol, dev[1] / (10 * tol), dev[2] / (10 * tol))
    print("largest relative deviation of the double-precision prototype from the fixture, by tolerance class")
    print("   tol        energy     d/d rho    d/d grad (on the scale given in the fixture)")
    for tol in sorted(classes):
        print("   %.1e    %.1e    %.1e    %.1e" % ((tol,) + tuple(classes[tol])))
    ok = worst <= 1.0
    print("largest deviation / allowed = %.3g  %s" % (worst, "ok" if ok else "FAILED"))
    return ok


# ----------------------------------------------------------------------------
# checks and reports
def self_test():
    ok = True

    def check(name, value, low, high):
        nonlocal ok
        good = low <= value <= high
        ok = ok and good
        print("%-64s %-12s %s" % (name, nstr(value, 4), "ok" if good else "FAILED"))

    tiny = mpf("1e-12")
    print("-- the constants and the exchange hole")
    check("T1  |3pi/4 + Ga(0)| with E from the regularity condition", abs(3 * pi / 4 + g_a(tiny, E_EXACT, FC_EXACT)), 0, 1e-20)
    check("T2  3pi/4 + Ga(0) with the published E (libxc comment: ~1.4e-8)", 3 * pi / 4 + g_a(tiny, E_PUBLISHED, FC_PUBLISHED), 1.3e-8, 1.5e-8)
    check("T3  relative rounding of the published Fc1 (libxc comment: ~6e-9)", abs(FC_EXACT[0] / FC_PUBLISHED[0] - 1), 5e-9, 7e-9)
    check("T4  relative rounding of the published Fc2 (libxc comment: ~8e-9)", abs(FC_EXACT[1] / FC_PUBLISHED[1] - 1), 7e-9, 9e-9)
    check("T5  |EG(0) - published EGa1|", abs(hole_eg(mpf("1e-6"), "libxc") - EGA_PUBLISHED[0]), 0, 1e-10)
    print("-- limits of the enhancement factor")
    check("T6  |f(w=0, s->0) - 1|   (LDA limit)", abs(enhancement(0, "1e-8") - 1), 0, 1e-8)
    worst = max(abs(enhancement(w, "1e-8") / f_lda_sr(w) - 1) for w in ("0.05", "0.2", "0.5", "1", "2", "5"))
    check("T7  max |f(w, s->0) / exact short-range LDA - 1|, w <= 5", worst, 0, 1e-2)
    worst = max(abs(enhancement("13.999", s) * (mpf("13.999") / mpf("14.001")) ** 2 / enhancement("14.001", s) - 1)
                for s in ("0.3", "1.5", "5"))
    check("T8  mismatch of the two branches across w = 14 (cancelling terms)", worst, 0, 1e-3)
    worst = max(abs(enhancement(0, s) / f_pbe(s) - 1) for s in ("0.2", "0.87", "2", "4.08"))
    check("T9  max |f(w=0, s) / F_PBE(s) - 1| at four s (model hole, not exact)", worst, 4e-3, 6e-3)
    print("-- energy density and derivatives")
    rho, grad = ("0.31", "0.07"), (("0.11", "-0.2", "0.05"), ("-0.03", "0.02", "0.04"))
    v = evaluate(rho, grad)
    r, g = mpf(rho[0]), [mpf(x) for x in grad[0]]
    gamma = sqrt(sum(x * x for x in g))
    omega = mpf(OMEGA_HSE06)
    h = r * mpf("1e-14")
    fd = (channel_energy(r + h, gamma, omega) - channel_energy(r - h, gamma, omega)) / (2 * h)
    check("T10 d e/d rho: mpmath.diff against a central difference", abs(fd / v["dexdd"][0] - 1), 0, 1e-20)
    hx = mpf("1e-16")
    def e_of_gx(x):
        return channel_energy(r, sqrt(x * x + g[1] ** 2 + g[2] ** 2), omega)
    fd = (e_of_gx(g[0] + hx) - e_of_gx(g[0] - hx)) / (2 * hx)
    check("T11 d e/d(d_x rho): chain rule against a central difference", abs(fd / v["dexdgd"][0][0] - 1), 0, 1e-20)
    n_tot, g_tot = mpf("0.4"), mpf("0.25")
    w_tot = omega / cbrt(3 * pi ** 2 * n_tot)
    s_tot = g_tot / (2 * cbrt(3 * pi ** 2) * n_tot ** (mpf(4) / 3))
    e_unpol = -mpf(3) / 4 * cbrt(3 / pi) * n_tot ** (mpf(4) / 3) * enhancement(w_tot, rescale(s_tot))
    half = evaluate((n_tot / 2, n_tot / 2), ((g_tot / 2, 0, 0), (g_tot / 2, 0, 0)))
    check("T12 spin scaling: two equal channels against the total-density form", abs(half["e"] / e_unpol - 1), 0, 1e-40)
    print("-- closed form against the defining integral")
    pairs = (("0", "0.5"), ("0.05", "0.02"), ("0.3", "1.3"), ("1", "4"), ("2.5", "0.5"), ("6", "8.5"), ("20", "1.3"))
    check("T13 max |closed form - quadrature of the hole| / |f|, 7 points", hole_integral_deviation(pairs), 0, 1e-18)
    print("-- tolerance envelope at the fixture points")
    worst = mpf(0)
    for rho_s in SPIN_DENSITIES:
        for s_raw in REDUCED_GRADIENTS:
            w, _ = channel_variables(mpf(rho_s), mpf(1), omega)
            worst = max(worst, rounding_error(w, rescale(s_raw)) / tolerance(w))
    check("T14 max (16-digit rounding error of the direct formula) / tolerance", worst, 0, 0.1)
    print("self-test passed" if ok else "self-test FAILED")
    return ok


def report():
    ws = ("0", "0.02", "0.05", "0.1", "0.2", "0.3", "0.5", "0.7", "1", "1.5", "2", "3", "5")

    def grid(a, b, n):
        return [mpf(a) + (mpf(b) - mpf(a)) * i / n for i in range(n + 1)]

    def largest(s_values, fa, fb):
        best = (mpf(0), None, None)
        for s in s_values:
            for w in ws:
                r = abs(fa(w, s) / fb(w, s) - 1)
                if r > best[0]:
                    best = (r, s, w)
        return "%s (s = %s, w = %s)" % (nstr(best[0], 2), nstr(best[1], 3), best[2])

    lib = lambda w, s: enhancement(w, s, "libxc")
    org = lambda w, s: enhancement(w, s, "hse-original")
    print("Relative differences of the enhancement factor f(w, s); w = omega/kF on the grid", " ".join(ws))
    print("(a) constants E, Fc1, Fc2: exact (libxc 7.1.2) against published (Quantum ESPRESSO 7.6), same s")
    print("    s <= 0.08 (three-term EG in the latter)  :", largest(grid("0.0005", "0.08", 40), lib, org))
    print("    0.08 < s < 1                             :", largest(grid("0.0801", "0.9999", 60), lib, org))
    print("    1 <= s <= 8.3                            :", largest(grid("1", "8.3", 73), lib, org))
    print("(b) rescaling of s: libxc 7.1.2 against Heyd (same constants)")
    for lo, hi in (("1", "2"), ("2", "5"), ("5", "8.3"), ("8.3", "30")):
        print("    %4s <= s_raw <= %-4s                     :" % (lo, hi),
              largest(grid(lo, hi, 60), lambda w, s: enhancement(w, rescale(s, "libxc")),
                      lambda w, s: enhancement(w, rescale(s, "hse-original"))))
    print("    jump of the rescaled s at s_raw = 1      :", nstr(1 - rescale(1), 4), " and at 15:", nstr(SMAX - rescale(15), 4))
    print("    relative jump of f at s_raw = 1          :",
          ", ".join("%s (w = %s)" % (nstr(enhancement(w, mpf(1) - mpf("1e-12")) / enhancement(w, rescale(1)) - 1, 3), w)
                    for w in ("0", "0.1", "0.3", "1")))
    print("(c) omega = 0 limit against the PBE enhancement factor, (f - F_PBE)/F_PBE")
    pos, neg = (mpf(0), None), (mpf(0), None)
    for s in grid("0.001", "5", 500):
        d = enhancement(0, s) / f_pbe(s) - 1
        pos = max(pos, (d, s))
        neg = min(neg, (d, s))
    print("    0 < s <= 5: from %s (s = %s) to %s (s = %s)" % (nstr(neg[0], 3), nstr(neg[1], 3), nstr(pos[0], 3), nstr(pos[1], 3)))
    print("(d) rounding error of a 16-digit evaluation of the direct formula (largest over s = 0.09 ... 8)")
    for w in ("0.3", "1", "2", "4", "6", "8", "10", "12", "13.9", "14.1", "50"):
        err = max(rounding_error(w, s) for s in ("0.09", "0.2", "0.5", "0.999", "2", "4", "8"))
        print("    w = %-5s %-9s tolerance %.1e   f(s = 0.5) = %s" % (w, nstr(err, 2), tolerance(w), nstr(enhancement(w, "0.5"), 4)))
    return True


def print_point(values, omega):
    rho, grad = values[0:2], (values[2:5], values[5:8])
    v = evaluate(rho, grad, omega)
    for sp, name in enumerate(("up", "down")):
        t = enhancement_terms(v["w"][sp], v["s"][sp])
        print("channel %-4s w = %s  s_raw = %s  s = %s" % (name, nstr(v["w"][sp], 20), nstr(v["s_raw"][sp], 20), nstr(v["s"][sp], 20)))
        for key in ("H", "F", "EG", "term1", "term2", "term3", "term4", "term5"):
            print("   %-6s %s" % (key, nstr(t[key], 20)))
        print("   f      %s" % nstr(enhancement(v["w"][sp], v["s"][sp]), 20))
        print("   e_s    %s   dexdd %s   vsigma %s" % (nstr(v["e_s"][sp], 20), nstr(v["dexdd"][sp], 20), nstr(v["vsigma"][sp], 20)))
        print("   dexdgd %s" % " ".join(nstr(x, 20) for x in v["dexdgd"][sp]))
    print("exc = %s   (energy per volume %s)" % (nstr(v["exc"], 20), nstr(v["e"], 20)))
    return True


def compare_pyscf(omega=OMEGA_HSE06, libxc_module=None):
    """Compare the fixture points with GGA_X_WPBEH of libxc, called through PySCF.

    Not executed against PySCF when this file was written (only against a stand-in module).
    """
    import numpy as np
    if libxc_module is None:
        from pyscf.dft import libxc as libxc_module
    version = libxc_module.__version__
    print("libxc version reported by PySCF:", version)
    if tuple(int(x) for x in version.split(".")[:2]) < (7, 1):
        print("libxc older than 7.1: the definition of GGA_X_WPBEH differs, comparison refused")
        return False
    rows = fixture_rows(omega)
    arr = np.array([[float(x) for x in row] for row in rows])
    rho_up = np.vstack([arr[:, 0], arr[:, 2], arr[:, 3], arr[:, 4]])
    rho_dn = np.vstack([arr[:, 1], arr[:, 5], arr[:, 6], arr[:, 7]])
    exc, vxc = libxc_module.eval_xc("GGA_X_WPBEH,", (rho_up, rho_dn), spin=1, deriv=1, omega=float(omega))[:2]
    exc0 = libxc_module.eval_xc("GGA_X_WPBEH,", (rho_up, rho_dn), spin=1, deriv=1)[0]
    vrho, vsigma = np.asarray(vxc[0]), np.asarray(vxc[1])
    if np.allclose(exc, exc0, rtol=1e-6, atol=0.0):
        print("the omega argument had no effect: check how omega reaches libxc")
        return False
    col = {name: i for i, name in enumerate(COLUMNS)}
    tol = np.maximum(arr[:, col["tol_up"]], arr[:, col["tol_dn"]])
    ref_e = arr[:, col["e_up"]] + arr[:, col["e_dn"]]
    weight = (np.abs(arr[:, col["e_up"]]) * arr[:, col["tol_up"]] + np.abs(arr[:, col["e_dn"]]) * arr[:, col["tol_dn"]])
    checks = [("exc", np.abs(np.asarray(exc) * (arr[:, 0] + arr[:, 1]) - ref_e) / (100 * weight))]
    for sp, name in enumerate(("up", "dn")):
        t = arr[:, col["tol_" + name]]
        checks.append(("vrho_" + name, np.abs(vrho[:, sp] / arr[:, col["dexdd_" + name]] - 1) / (1000 * t)))
        # vsigma is exactly zero where the rescaled gradient is constant (s_raw > 15): compare on the
        # scale max(|reference|, 1e-6 |e_s| / |grad rho_s|^2)
        ref_vs = arr[:, col["vsigma_upup" if sp == 0 else "vsigma_dndn"]]
        g = arr[:, 2 + 3 * sp:5 + 3 * sp]
        scale = np.maximum(np.abs(ref_vs), 1e-6 * np.abs(arr[:, col["e_" + name]]) / np.sum(g * g, axis=1))
        checks.append(("vsigma_" + name * 2, np.abs(vsigma[:, 2 * sp] - ref_vs) / (1000 * t * scale)))
    checks.append(("vsigma_updn (must vanish)", np.abs(vsigma[:, 1]) / 1e-300))
    ok = True
    for name, ratio in checks:
        worst = int(np.argmax(ratio))
        good = bool(ratio[worst] <= 1.0)
        ok = ok and good
        print("%-26s largest deviation / allowed = %.3g at point %d (tolerance class %.1e)  %s"
              % (name, ratio[worst], worst, tol[worst], "ok" if good else "FAILED"))
    print("allowed deviation: 100 x tol for the energy, 1000 x tol for the derivatives (tol from the fixture)")
    print("comparison passed" if ok else "comparison FAILED")
    return ok


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--report", action="store_true", help="print the effect of the formula choices")
    ap.add_argument("--dump", metavar="FILE", help="write the fixture for the unit tests")
    ap.add_argument("--point", nargs=8, metavar="X", help="rho_up rho_dn and the two gradients")
    ap.add_argument("--double", action="store_true", help="double-precision prototype against the fixture")
    ap.add_argument("--compare-pyscf", action="store_true", help="compare with libxc through PySCF")
    ap.add_argument("--omega", default=OMEGA_HSE06, help="screening parameter in 1/bohr (default 0.11)")
    args = ap.parse_args()
    if args.report:
        return 0 if report() else 1
    if args.dump:
        print("wrote", args.dump, "with", write_fixture(args.dump, args.omega), "points")
        return 0
    if args.point:
        return 0 if print_point(args.point, args.omega) else 1
    if args.double:
        return 0 if double_check(args.omega) else 1
    if args.compare_pyscf:
        return 0 if compare_pyscf(args.omega) else 1
    return 0 if self_test() else 1


if __name__ == "__main__":
    sys.exit(main())
